INSERT INTO public.alerts (id, astronaut_id, "timestamp", severity, alert_type, message, acknowledged, trigger_metric, recommended_action, hazard_domain) VALUES ('c561fa00', 'ASTRO-03', '2026-11-15 07:34:47.737126+00', 'WARNING', 'HYPOGLYCEMIA', 'Low blood glucose (59 mg/dL). Post-exertion fuel deficit developing.', true, 'Glucose 59 mg/dL', 'Consume carbohydrate ration (15 g) and recheck capillary glucose in 15 minutes.', 'Metabolic & Nutrition') ON CONFLICT DO NOTHING;
