INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('81359876-adb2-4b36-a9ce-782edb9215f2', 'b7ce9825-ba34-4fd5-939f-14365bb520b1', 'ASTRO-02', 'dermal_radiation', '2026-11-15 06:31:26.854+00', 'warning', 'Offline clinical checklist guidance for Dermal / Radiation Erythema & Wound Check. Correlation flagged: elevated space weather/radiation exposure or symptomatic dermal note. Follow countermeasures and escalate if persistent.', '["Cleanse affected area gently with sterile saline; avoid harsh alcohol wipes in closed habitats.", "Check cumulative personal dosimeter and remain in polyethylene-shielded quarters during solar peaks.", "Capture follow-up macro photo at 12 hours to verify border stability or spreading."]', true, 'protocol-offline', NULL, '2026-11-15 06:31:26.915829+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('1c348b60-82e4-40b2-ba86-b8233baf8895', 'db-exam-ASTRO-01-01', 'ASTRO-01', 'ocular_ultrasound', '2026-11-14 10:26:20.965999+00', 'nominal', 'Bilateral optic nerve sheath diameter measured ~4.3 mm 3 mm posterior to retina with smooth posterior sclera and no globe flattening.', '["Continue routine SANS ultrasound cadence per mission flight plan.", "Log visual acuity or any transient peripheral blur in your next check-in."]', false, 'database-baseline', NULL, '2026-11-15 06:26:21.068412+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('d114b3c7-a96d-4906-8264-607b6d524911', 'eed1b4f3-709d-4e0d-bb81-3b60599ca188', 'ASTRO-02', 'dermal_radiation', '2026-11-15 07:22:43.509+00', 'warning', 'The image shows significant well-demarcated erythema and skin changes across the facial and cervical regions consistent with radiation dermatitis or acute skin reaction. Given the high ambient radiation telemetry context in transit, monitoring for progression, blistering, or desquamation is critical.', '["Cleanse the affected skin gently with mild soap and water.", "Apply recommended topical emollients or barrier creams per medical checklist.", "Avoid direct sunlight and friction from garments or gear.", "Monitor skin daily and document changes photographically."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:22:45.125661+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('3ceb6cd5-8f55-4ef4-bc61-ccbb1c7a320f', 'b7a37816-09fa-4531-8c56-a4b12dd079e0', 'ASTRO-01', 'dermal_radiation', '2026-11-15 07:36:42.236+00', 'critical', 'Significant skin erythema and hyperpigmentation observed across the right cheek, jawline, and neck region. Telemetry indicates critical vital signs including tachycardia (HR 141 bpm), hypoxemia (SpO2 88.6%), hypoglycemia (61 mg/dL), and elevated radiation exposure (133.3 uSv/h).', '["Initiate immediate supplemental oxygen to address hypoxemia (SpO2 88.6%).", "Administer oral glucose to treat hypoglycemia (61 mg/dL).", "Notify flight surgeon and Mission Control immediately for urgent clinical evaluation.", "Shelter crewmember in a designated low-radiation area due to elevated radiation levels."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:36:43.923655+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('ec5f3a1e-2b1e-4962-b113-46af71350669', '2187f8ec-c6e4-4aa1-970b-40399244b0a4', 'ASTRO-01', 'dermal_radiation', '2026-11-15 07:45:54.143+00', 'warning', 'Image reveals well-demarcated erythema involving the left cheek, preauricular area, and neck region under moderate ambient lighting. Skin texture appears intact without overt blistering, ulceration, or necrosis, consistent with moderate radiation dermatitis or localized dermal reaction given the flight environment.', '["Clean the affected dermal area gently with mild soap and sterile water.", "Apply recommended soothing barrier cream or non-scented moisturizer per flight medical kit guidelines.", "Monitor skin condition daily for signs of blistering, peeling, or increased pain.", "Avoid direct friction or exposure to potential irritants."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:45:55.592089+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('3b5fbdf4-5e18-4cfa-81f8-1675c32d33d5', '47072435-f267-4cde-83c0-0ff6191fe333', 'ASTRO-01', 'dermal_radiation', '2026-11-15 07:53:40.468+00', 'nominal', 'Image quality is acceptable with clear facial and upper torso visibility. Skin appears intact with normal coloration, showing no signs of acute radiation erythema, rash, lesions, or wound formation.', '["Continue standard routine hygiene and skin monitoring", "Log daily dermal check per NASA protocol"]', false, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:53:44.151103+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('ab3fad8d-b26a-4c5f-ad4d-692d103a1b4c', '5bb4a82b-1b2a-4afa-88ea-85ed3351acf7', 'ASTRO-01', 'dermal_radiation', '2026-11-15 07:54:32.554+00', 'nominal', 'Image quality is acceptable for basic dermal review. Visible skin on the face, neck, and upper chest appears intact with normal coloration. No acute signs of radiation erythema, blistering, excoriation, or localized wounds are observable.', '["Log findings in the onboard medical database", "Continue routine hygiene and standard skin monitoring", "Report any new or developing skin irritation to the flight surgeon during the next comm pass"]', false, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:54:34.119029+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('c5d31673-727a-40f4-a38d-0500fdb43790', '167ab52c-5ccb-413e-8eed-9b73ff077cbe', 'ASTRO-01', 'dermal_radiation', '2026-11-15 07:55:55.097+00', 'nominal', 'Image shows motion blur and suboptimal framing for a dermal or radiation erythema check of the targeted skin area. No acute cutaneous lesions, severe erythema, or open wounds are visibly discernible due to image quality limitations.', '["Retake the photograph under stable lighting conditions with proper focus on the skin region of interest.", "Ensure no motion blur is present during image capture.", "Log self-care observations in the medical module if any localized discomfort or redness develops."]', false, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 07:55:57.300381+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('76ac3884-a231-4e8b-81fd-770d846b4d37', '0727d3dd-28cb-4886-8d96-8b5af36c342a', 'ASTRO-01', 'ocular_ultrasound', '2026-11-15 10:16:40.828+00', 'critical', 'The uploaded image is a standard personal photograph of an individual in a residential setting, not an ocular or optic nerve sheath ultrasound image required by the SANS Check protocol. No biomedical imaging data is present to evaluate for Spaceflight-Associated Neuro-ocular Syndrome (SANS).', '["Discontinue current non-compliant image upload.", "Access the NASA onboard medical imaging software and select the correct Ocular / Optic Nerve Sheath Ultrasound protocol.", "Repeat the ultrasound scan ensuring proper transducer placement and capture the required DICOM images for SANS evaluation."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 10:16:43.977366+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('a96975f9-9749-4953-833f-98954a83b760', '8208af8f-63c1-43e9-b5fa-0b19449843bb', 'ASTRO-01', 'dermal_radiation', '2026-11-15 10:17:36.934+00', 'warning', 'Image reveals well-demarcated erythema and hyperpigmentation localized to the sun-exposed lateral facial and neck regions, consistent with acute radiation dermatitis or severe solar erythema. Given the elevated telemetry radiation level (226.1 uSv/h), monitoring for blistering or secondary skin breakdown is indicated.', '["Clean the affected skin gently with mild soap and water.", "Apply recommended soothing barrier cream or topical corticosteroid per flight surgeon protocol.", "Avoid further direct radiation or UV exposure by remaining inside shielded habitat areas.", "Document skin changes daily and report increased pain, blistering, or signs of infection."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 10:17:40.585782+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('ae5068a0-289f-4967-a540-38b45b6a8e6d', '1a8cc0b3-7760-47d4-9932-f14aedd7ec3c', 'ASTRO-01', 'dermal_radiation', '2026-11-15 12:27:53.166+00', 'nominal', 'Offline Skin & Radiation Erythema saved on device. Follow checklist guidelines and re-evaluate in Ground telemetry window.', '["Position camera 20 cm from forearm, neck, or suit pressure zone under neutral cabin LEDs.", "Note tenderness, itching, warmth, or onset relative to EVA suit doffing or solar alerts.", "Baseline: Intact barrier, uniform skin tone, no induration or expanding erythema."]', false, 'device-offline', 'data:image/jpeg;base64,', '2026-11-15 12:28:05.182998+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('2fc03f87-efcd-4d6d-80e3-324a6fed44c8', '44a2737b-81df-464b-952a-91ec129a7e1a', 'ASTRO-01', 'dermal_radiation', '2026-11-15 12:38:51.817+00', 'warning', 'Offline clinical checklist guidance for Dermal / Radiation Erythema & Wound Check. Correlation flagged: elevated space weather/radiation exposure or symptomatic dermal note. Follow countermeasures and escalate if persistent.', '["Cleanse affected area gently with sterile saline; avoid harsh alcohol wipes in closed habitats.", "Check cumulative personal dosimeter and remain in polyethylene-shielded quarters during solar peaks.", "Capture follow-up macro photo at 12 hours to verify border stability or spreading."]', true, 'protocol-offline', NULL, '2026-11-15 12:38:51.862802+00') ON CONFLICT DO NOTHING;
INSERT INTO public.imaging_assessments (id, client_id, astronaut_id, exam_type, recorded_at, severity, findings, recommended_actions, ground_consult_required, analysis_source, thumbnail_data_url, created_at) VALUES ('725ef381-3bc0-4087-8e1f-134193f71d9e', '4243476a-98bd-4a94-82fa-814059791906', 'ASTRO-01', 'dermal_radiation', '2026-11-15 12:49:40.808+00', 'warning', 'Image reveals significant well-demarcated erythema and possible cutaneous irritation or radiation-associated skin reaction across the right cheek, jawline, and neck region. Given the elevated local radiation telemetry (Rad 226.5 uSv/h), this finding warrants close monitoring per dermal checklists.', '["Log affected skin area and monitor daily for changes in pain, blistering, or desquamation.", "Avoid direct sunlight or further environmental exposure in the planetary rover zone.", "Apply soothing, non-scented moisturizer or NASA-approved topical barrier cream if irritation persists."]', true, 'gemini-vision', 'data:image/jpeg;base64,', '2026-11-15 12:49:42.553556+00') ON CONFLICT DO NOTHING;
